(function(root){'use strict';const cloud=root.KANA_CLOUD,header=document.querySelector('.header-actions');
const status=document.createElement('button');status.type='button';status.className='account-status';status.textContent='neste dispositivo';status.setAttribute('aria-haspopup','dialog');header.prepend(status);
const modal=document.createElement('div');modal.className='account-modal';modal.hidden=true;modal.innerHTML='<div class="account-dialog" role="dialog" aria-modal="true" aria-labelledby="accountTitle"><button class="account-close" type="button" aria-label="Fechar">×</button><p class="eyebrow">conta</p><h2 id="accountTitle">Seu progresso.</h2><div id="accountGuest"><p>Entre com a mesma senha em qualquer aparelho. O progresso continua funcionando offline.</p><form id="accountForm"><input id="accountEmail" type="email" inputmode="email" autocomplete="email" placeholder="seu@email.com" required><input id="accountPassword" type="password" autocomplete="current-password" minlength="8" placeholder="senha (mínimo 8 caracteres)" required><button class="submit" type="submit">entrar</button><button class="account-secondary" id="createAccount" type="button">criar conta</button></form><button class="account-link" id="magicLink" type="button">receber link de acesso</button></div><div id="accountUser" hidden><strong id="accountEmailLabel"></strong><p id="syncDetail">Progresso sincronizado.</p><form id="passwordForm"><input id="newPassword" type="password" autocomplete="new-password" minlength="8" placeholder="criar ou alterar senha" required><button class="account-secondary" type="submit">salvar senha</button></form><button class="submit" id="syncNow" type="button">sincronizar agora</button><button class="account-signout" id="signOut" type="button">sair da conta</button></div><p class="account-feedback" id="accountFeedback" aria-live="polite"></p></div>';document.body.appendChild(modal);
const $=id=>document.getElementById(id),guest=$('accountGuest'),user=$('accountUser'),feedback=$('accountFeedback');function open(){modal.hidden=false;document.body.classList.add('modal-open');setTimeout(()=>guest.hidden||$('accountEmail').focus(),0);}function close(){modal.hidden=true;document.body.classList.remove('modal-open');feedback.textContent='';}status.onclick=open;modal.querySelector('.account-close').onclick=close;modal.onclick=e=>{if(e.target===modal)close();};addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)close();});
$('accountForm').onsubmit=async e=>{e.preventDefault();feedback.textContent='Entrando…';try{await cloud.auth.signInWithPassword($('accountEmail').value.trim(),$('accountPassword').value);await cloud.ready();feedback.textContent='Conta conectada e sincronizada.';}catch(error){feedback.textContent=error.message;}};
$('createAccount').onclick=async()=>{feedback.textContent='Criando conta…';try{await cloud.auth.signUpWithPassword($('accountEmail').value.trim(),$('accountPassword').value);await cloud.ready();feedback.textContent='Conta criada e sincronizada.';}catch(error){feedback.textContent=error.message;}};
$('magicLink').onclick=async()=>{const email=$('accountEmail').value.trim();if(!email){feedback.textContent='Digite seu e-mail primeiro.';return;}feedback.textContent='Enviando…';try{await cloud.auth.requestMagicLink(email);feedback.textContent='Link enviado. Use esta opção apenas para recuperar o acesso.';}catch(error){feedback.textContent=error.message;}};
$('passwordForm').onsubmit=async e=>{e.preventDefault();feedback.textContent='Salvando senha…';try{await cloud.auth.updatePassword($('newPassword').value);$('newPassword').value='';feedback.textContent='Senha salva. Agora você pode entrar em outro aparelho sem abrir o e-mail.';}catch(error){feedback.textContent=error.message;}};
$('signOut').onclick=async()=>{await cloud.signOut();};$('syncNow').onclick=async()=>{feedback.textContent='Sincronizando…';const result=await cloud.sync.releaseAndSynchronize();feedback.textContent=result?.status==='synced'?'Todos os aparelhos estão atualizados.':'Não foi possível concluir agora. Tentaremos novamente automaticamente.';};
function render(state){guest.hidden=state.signedIn;user.hidden=!state.signedIn;if(state.signedIn){$('accountEmailLabel').textContent=state.email||'Conta conectada';status.textContent=!state.online?'offline':state.connectionProblem?'reconectando…':state.syncing?'sincronizando…':'conectado';$('syncDetail').textContent=!state.online?'Suas respostas serão enviadas automaticamente quando a conexão voltar.':state.connectionProblem?'Tentando salvar seu progresso automaticamente.':'Seu progresso acompanha esta conta automaticamente.';}else status.textContent='neste dispositivo';}
cloud.sync.onChange(render);cloud.ready().then(session=>render({signedIn:Boolean(session),online:navigator.onLine,pending:root.KANA_DATA.repositories.queue.list().length,email:session?.user?.email||''})).catch(()=>render({signedIn:Boolean(cloud.auth.current),online:navigator.onLine,pending:root.KANA_DATA.repositories.queue.list().length,email:cloud.auth.current?.user?.email||''}));
})(window);
